import{_ as e,o,c as r,a1 as c}from"./chunks/framework.BKrM4vFX.js";const g=JSON.parse('{"title":"Карта документации","description":"Карта документации. mock-services — открытый тестовый стенд: моки банков-эквайрингов, облачных касс и ОФД по официальным протоколам провайдеров. Стенд нужен, чтобы проверить платёжную и фискальную интеграцию до договора с провайдером — с че","frontmatter":{"sourcePath":"docs/overview.md"},"headers":[{"level":1,"title":"Карта документации","slug":"Карта-документации","link":"#Карта-документации","children":[{"level":2,"title":"пометки VERIFY и FORK","slug":"пометки-verify-и-fork","link":"#пометки-verify-и-fork","children":[]},{"level":2,"title":"С чего начать","slug":"С-чего-начать","link":"#С-чего-начать","children":[]},{"level":2,"title":"Банки — эквайринг","slug":"Банки-эквайринг","link":"#Банки-эквайринг","children":[]},{"level":2,"title":"Кассы и ОФД","slug":"Кассы-и-ОФД","link":"#Кассы-и-ОФД","children":[]},{"level":2,"title":"Как устроена документация","slug":"Как-устроена-документация","link":"#Как-устроена-документация","children":[]},{"level":2,"title":"Что полезно знать перед интеграцией","slug":"Что-полезно-знать-перед-интеграцией","link":"#Что-полезно-знать-перед-интеграцией","children":[]}]}],"relativePath":"docs/overview.md","filePath":"docs/overview.md"}'),d={name:"docs/overview.md"};function a(i,t,n,s,l,h){return o(),r("div",null,[...t[0]||(t[0]=[c('<h1 id="Карта-документации" tabindex="-1">Карта документации <a class="header-anchor" href="#Карта-документации" aria-label="Permalink to &quot;Карта документации&quot;">​</a></h1><nav class="doc-static-toc" aria-label="Оглавление"><p class="doc-static-toc__title">Оглавление</p><ul><li class="doc-static-toc__item doc-static-toc__item--1"><a class="doc-static-toc__link" href="#Карта-документации">Карта документации</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#пометки-verify-и-fork">пометки VERIFY и FORK</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#С-чего-начать">С чего начать</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Банки-эквайринг">Банки — эквайринг</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Кассы-и-ОФД">Кассы и ОФД</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Как-устроена-документация">Как устроена документация</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Что-полезно-знать-перед-интеграцией">Что полезно знать перед интеграцией</a></li></ul></nav><p><strong>mock-services</strong> — открытый тестовый стенд: моки банков-эквайрингов, облачных касс и ОФД по официальным протоколам провайдеров. Стенд нужен, чтобы проверить платёжную и фискальную интеграцию <strong>до договора с провайдером</strong> — с честными схемами, кодами ошибок, сценариями отказов и подсказками «что не так в запросе».</p><p>Этот раздел — точка входа: что читать по порядку, где лежит документация по каждому провайдеру и как устроен репозиторий.</p><h2 id="пометки-verify-и-fork" tabindex="-1">пометки VERIFY и FORK <a class="header-anchor" href="#пометки-verify-и-fork" aria-label="Permalink to &quot;пометки VERIFY и FORK&quot;">​</a></h2><p>В документации встречаются пометки <code>[VERIFY]</code> и <code>[FORK]</code> — они помогают отличить проверенные факты от допущений:</p><ul><li><code>[VERIFY]</code> — деталь <strong>не проверена</strong> по официальной документации провайдера: публичная документация не раскрывает поле, схему, статус или поведение. Мок делает консервативное допущение, которое нужно пересверить при получении доступа к кабинету/тест-контуру. Такие места перечислены в гайде провайдера и в <code>services/&lt;name&gt;-mock/README.md</code>.</li><li><code>[FORK]</code> — <strong>сознательное отличие</strong> мока от формулировки/поведения провайдера, зафиксированное как документированный форк. Причина: противоречие в документации, отсутствие публичной спеки, локальная конвенция стенда (например, синтетические тестовые карты, cursor как индекс, повторный Login выдаёт новый marker). Форк не является утверждением о протоколе — перед переносом в production сверьте с официальной докой.</li></ul><p>Легенда вынесена сюда, чтобы не повторять её в каждом гайде. В тексте пометки оставлены как есть, но теперь они ссылаются на этот раздел.</p><h2 id="С-чего-начать" tabindex="-1">С чего начать <a class="header-anchor" href="#С-чего-начать" aria-label="Permalink to &quot;С чего начать&quot;">​</a></h2><ol><li><strong><a href="/mock-services/#быстрый-старт">Быстрый старт</a></strong> — поднять стенд: <code>docker compose up</code> (все десять сервисов) или <code>npm run start:&lt;сервис&gt;</code> без Docker (нужен только Node ≥ 18).</li><li><strong>Интеграция за 10 минут</strong> по вашему провайдеру — таблицы ниже. Гайд ведёт от <code>getToken</code>/<code>Init</code> до первого успешного платежа или чека и объясняет, что мок проверит за вас.</li><li><strong>README сервиса</strong> — когда нужны детали: поля, подписи, статусы, env и ссылки на официальные разделы документации провайдера.</li><li><strong>OpenAPI 3.1</strong> — машинкочитаемые спецификации каждого сервиса: ссылки в таблицах ниже, на живом стенде — <code>GET /openapi.json</code>.</li></ol><h2 id="Банки-эквайринг" tabindex="-1">Банки — эквайринг <a class="header-anchor" href="#Банки-эквайринг" aria-label="Permalink to &quot;Банки — эквайринг&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Провайдер</th><th>Что эмулирует</th><th>Порт</th><th>Документы</th></tr></thead><tbody><tr><td><strong>Т-Банк</strong></td><td>EACQ: <code>Init</code> → платёжная форма → нотификации → <code>Confirm</code>/<code>Cancel</code>; Мультирасчёты (сделки, выплаты e2c), СБП QR, рекурренты, чарджбэки, верификация счетов (AV)</td><td>3100</td><td><a href="./integration/tbank-eacq">гайд</a> · <a href="https://github.com/rucorp/mock-services/blob/main/docs/openapi/tbank-mock.openapi.json" target="_blank" rel="noreferrer">OpenAPI</a></td></tr><tr><td><strong>ЮKassa</strong></td><td>REST <code>/v3</code>: Basic Auth + <code>Idempotence-Key</code>, two-stage с частичным <code>capture</code>, возвраты, confirmation-страница, вебхуки</td><td>3102</td><td><a href="./integration/yookassa">гайд</a></td></tr><tr><td><strong>Альфа-Банк</strong></td><td>интернет-эквайринг REST <code>/payment/rest/*.do</code>: <code>register</code>/<code>registerPreAuth</code> → <code>formUrl</code>, <code>deposit</code> ≤ холда, <code>reverse</code>, <code>refund</code>, callback HTTP GET с checksum HMAC-SHA256</td><td>3104</td><td><a href="./integration/alfa">гайд</a> · <a href="https://github.com/rucorp/mock-services/blob/main/docs/openapi/alfa-mock.openapi.json" target="_blank" rel="noreferrer">OpenAPI</a></td></tr><tr><td><strong>Сбербанк</strong></td><td>Ecom REST v1.1.11.1 <code>/ecomm/gw/partner/api/v1/*.do</code>: <code>register</code>, форма и ACS <code>111111</code>, <code>deposit</code>/<code>reverse</code>/<code>refund</code>/<code>decline</code>, callback JSON с ACK 200 и retry</td><td>3105</td><td><a href="./integration/sber">гайд</a> · <a href="https://github.com/rucorp/mock-services/blob/main/docs/openapi/sber-mock.openapi.json" target="_blank" rel="noreferrer">OpenAPI</a></td></tr><tr><td><strong>ВТБ</strong></td><td>SMB E-commerce API <code>/openapi/smb/efcp/e-commerce/v1/</code>: OAuth 2.0 <code>client_credentials</code>, <code>orders</code>/<code>preauth</code>/<code>complete</code>/<code>cancel</code>/<code>refunds</code>, ордер живёт 20 минут</td><td>3106</td><td><a href="./integration/vtb">гайд</a> · <a href="https://github.com/rucorp/mock-services/blob/main/docs/openapi/vtb-mock.openapi.json" target="_blank" rel="noreferrer">OpenAPI</a></td></tr></tbody></table><h2 id="Кассы-и-ОФД" tabindex="-1">Кассы и ОФД <a class="header-anchor" href="#Кассы-и-ОФД" aria-label="Permalink to &quot;Кассы и ОФД&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Провайдер</th><th>Что эмулирует</th><th>Порт</th><th>Документы</th></tr></thead><tbody><tr><td><strong>OFD Ferma</strong></td><td>облачная касса по 54-ФЗ: <code>sell</code>/<code>buy</code> с возвратами и коррекциями, авансы и зачёты, маркировка «Честный ЗНАК», очередь ОФД, смены ККТ 24 ч и Z-отчёты, ресурс ФН</td><td>3101</td><td><a href="./integration/ferma-ofd">гайд</a> · <a href="https://github.com/rucorp/mock-services/blob/main/docs/openapi/kassa-mock.openapi.json" target="_blank" rel="noreferrer">OpenAPI</a></td></tr><tr><td><strong>АТОЛ Онлайн</strong></td><td>direct API v4 (ФФД 1.05): <code>getToken</code> на 24 ч, шесть операций фискализации, идемпотентность <code>external_id</code>, отчёт <code>wait → done|fail</code> с ФД/ФП</td><td>3103</td><td><a href="./integration/atol">гайд</a> · <a href="https://github.com/rucorp/mock-services/blob/main/docs/openapi/atol-mock.openapi.json" target="_blank" rel="noreferrer">OpenAPI</a></td></tr><tr><td><strong>Первый ОФД (OKassa)</strong></td><td>асинхронная очередь заявок <code>/api/external/queue/v1/transaction/{type}</code> → <code>requestId</code>, статусы <code>IN_PROGRESS → COMPLETED|ERROR</code>, сверка чеков за период</td><td>3107</td><td><a href="./integration/first-ofd">гайд</a> · <a href="https://github.com/rucorp/mock-services/blob/main/docs/openapi/first-ofd-mock.openapi.json" target="_blank" rel="noreferrer">OpenAPI</a></td></tr><tr><td><strong>Контур.ОФД</strong></td><td>чтение и сверка: Sid + API key, организации, кассы, фискальные документы (суммы в копейках) — без создания чека</td><td>3108</td><td><a href="./integration/kontur-ofd">гайд</a> · <a href="https://github.com/rucorp/mock-services/blob/main/docs/openapi/kontur-ofd-mock.openapi.json" target="_blank" rel="noreferrer">OpenAPI</a></td></tr><tr><td><strong>Такском</strong></td><td>read-only кабинет/ОФД, API v2: <code>POST /API/v2/Login</code> с <code>Integrator-ID</code> → <code>Session-Token</code> на 5 минут, <code>AccountList</code>, <code>NewDocuments</code> за 10 суток</td><td>3109</td><td><a href="./integration/taxcom">гайд</a> · <a href="https://github.com/rucorp/mock-services/blob/main/docs/openapi/taxcom-mock.openapi.json" target="_blank" rel="noreferrer">OpenAPI</a></td></tr></tbody></table><blockquote><p>Read-only адаптеры (Контур.ОФД, Такском) не умеют создавать чеки: они предназначены для сверки уже пробитых документов. Write API Такскома не моделируется.</p></blockquote><h2 id="Как-устроена-документация" tabindex="-1">Как устроена документация <a class="header-anchor" href="#Как-устроена-документация" aria-label="Permalink to &quot;Как устроена документация&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Слой</th><th>Где лежит</th><th>Для чего</th></tr></thead><tbody><tr><td><strong>Гайды «за 10 минут»</strong></td><td><a href="./integration/tbank-eacq"><code>docs/integration/</code></a></td><td>Поднять сервис, провести первый платёж/чек, увидеть сценарии отказов</td></tr><tr><td><strong>Официальная документация провайдеров</strong></td><td>ссылки в гайдах интеграции и README сервисов</td><td>Первоисточник: эндпоинты, поля, подписи, статусы</td></tr><tr><td><strong>OpenAPI 3.1</strong></td><td><a href="https://github.com/rucorp/mock-services/blob/main/docs/openapi/tbank-mock.openapi.json" target="_blank" rel="noreferrer"><code>docs/openapi/</code></a></td><td>Машинкочитаемые спецификации; на живом стенде — <code>GET /openapi.json</code></td></tr><tr><td><strong>Манифесты протоколов</strong></td><td><code>protocols/&lt;provider&gt;.json</code></td><td>Декларация операций для детектора дрейфа (<code>npm run check:drift</code>)</td></tr><tr><td><strong>Сервисы</strong></td><td><a href="./../services/tbank-mock/README"><code>services/&lt;provider&gt;-mock/</code></a></td><td>Env-переменные, эндпоинты управления (<code>/mock/*</code>), сценарии, журнал</td></tr><tr><td><strong>Ядро</strong></td><td><a href="./../packages/core/README"><code>packages/core/</code></a></td><td>Общая инфраструктура адаптеров: ошибки, часы, песочницы, вебхуки</td></tr><tr><td><strong>Проект</strong></td><td><a href="./../CONTRIBUTING">CONTRIBUTING</a> · <a href="./../SECURITY">SECURITY</a></td><td>Правила вклада, модель угроз и требования к развёртыванию</td></tr></tbody></table><p>Публичная документация самодостаточна: детали протоколов приведены со ссылками на официальную документацию провайдеров в гайдах и README сервисов.</p><h2 id="Что-полезно-знать-перед-интеграцией" tabindex="-1">Что полезно знать перед интеграцией <a class="header-anchor" href="#Что-полезно-знать-перед-интеграцией" aria-label="Permalink to &quot;Что полезно знать перед интеграцией&quot;">​</a></h2><ul><li><strong>Это не продакшен и не drop-in.</strong> Мок повторяет клиентский контракт провайдера, но одной смены URL для перехода в бой недостаточно: проверьте конфигурацию, безопасность и условия интеграции.</li><li><strong>Ошибка — это подсказка.</strong> Любой отказ мока содержит код, человекочитаемое объяснение, проблемное поле и ссылку на официальный раздел документации.</li><li><strong>Сценарии отказов переключаются.</strong> Недостаток средств, таймаут, дубль вебхука, чарджбэк, отказ ККТ — сценарием или переменной окружения, а не «ждём боевой инцидент».</li><li><strong>Виртуальные часы.</strong> <code>POST /mock/time</code> двигает время стенда: TTL токенов, смены 24 ч, устаревание резерва ФН и retry вебхуков проверяются без ожидания.</li><li><strong>Развёртывание наружу.</strong> Порты по умолчанию слушают <code>127.0.0.1</code>; для публичного стенда обязательны <code>MOCK_HOSTED=1</code>, токены <code>/mock/*</code> и админки, TLS и egress-фильтр — см. <a href="./../SECURITY">SECURITY</a>.</li></ul><hr><p>Репозиторий: <a href="https://github.com/rucorp/mock-services" target="_blank" rel="noreferrer">github.com/rucorp/mock-services</a> · Лицензия Apache-2.0 · © 2026 ООО «Аксиома»</p>',22)])])}const m=e(d,[["render",a]]);export{g as __pageData,m as default};
